/**
 * Reads mockup/controls.json and writes:
 *   mockup/controls.data.js   — the data the mockup page loads (file:// safe, no fetch)
 *   docs/CONTROL-MAP.md       — the readable version of the same list
 *
 * Run with: node mockup/build-control-map.mjs
 *
 * The JSON is the only source of truth. Both outputs are overwritten, so edit
 * the JSON (or the mockup) rather than the generated files.
 */
import { readFile, writeFile } from 'node:fs/promises'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const HERE = dirname(fileURLToPath(import.meta.url))
const ROOT = join(HERE, '..')

const STATUSES = ['live', 'partial', 'planned']
const KINDS = ['button', 'toggle', 'slider', 'fader', 'stepper', 'knob', 'pad', 'gesture', 'readout', 'meter', 'popover', 'block']
const REQUIRED = ['id', 'group', 'label', 'kind', 'status', 'does']

const raw = await readFile(join(HERE, 'controls.json'), 'utf8')
const data = JSON.parse(raw)

/* ---------- validate ---------- */
const problems = []
const groupIds = new Set(data.groups.map((group) => group.id))
const seen = new Set()

for (const [index, control] of data.controls.entries()) {
  const where = control.id || `#${index + 1}`
  for (const field of REQUIRED) {
    if (!control[field]) problems.push(`${where}: missing "${field}"`)
  }
  if (seen.has(control.id)) problems.push(`${where}: duplicate id`)
  seen.add(control.id)
  if (control.group && !groupIds.has(control.group)) problems.push(`${where}: unknown group "${control.group}"`)
  if (control.status && !STATUSES.includes(control.status)) problems.push(`${where}: unknown status "${control.status}"`)
  if (control.kind && !KINDS.includes(control.kind)) problems.push(`${where}: unknown kind "${control.kind}"`)
}

if (!Array.isArray(data.sections) || data.sections.length === 0) {
  problems.push('sections: missing or empty')
} else {
  const sectionIds = new Set()
  for (const [index, section] of data.sections.entries()) {
    const where = section.id || `section #${index + 1}`
    for (const field of ['id', 'label', 'scope']) {
      if (!section[field]) problems.push(`${where}: missing "${field}"`)
    }
    if (sectionIds.has(section.id)) problems.push(`${where}: duplicate section id`)
    sectionIds.add(section.id)
  }
}

if (problems.length > 0) {
  console.error('controls.json is not valid:\n  ' + problems.join('\n  '))
  process.exit(1)
}

/* ---------- number the controls, in reading order ---------- */
let n = 0
const numbered = data.controls.map((control) => ({ ...control, n: ++n }))

/* ---------- mockup data file ---------- */
const payload = { ...data, controls: numbered }
const banner = '/* Generated by mockup/build-control-map.mjs from mockup/controls.json — do not edit by hand. */\n'
await writeFile(
  join(HERE, 'controls.data.js'),
  `${banner}window.DEX_CONTROLS = ${JSON.stringify(payload, null, 2)}\n`,
  'utf8'
)

/* ---------- docs ---------- */
const count = (status) => numbered.filter((control) => control.status === status).length
const esc = (text) => String(text).replace(/\|/g, '\\|')

const byGroup = data.groups.map((group) => ({
  ...group,
  controls: numbered.filter((control) => control.group === group.id)
}))

const lines = []
lines.push('# Dex control map')
lines.push('')
lines.push(
  'Every control drawn in [`mockup/xdj-mixer-alt.html`](../mockup/xdj-mixer-alt.html), in screen order, with what it'
)
lines.push('actually does in Dex today. Generated from [`mockup/controls.json`](../mockup/controls.json) by')
lines.push('`node mockup/build-control-map.mjs` — edit the JSON, not this file.')
lines.push('')
lines.push('| Status | Meaning |')
lines.push('| --- | --- |')
lines.push('| **LIVE** | Has a working control in the app. |')
lines.push('| **PARTIAL** | The app has part of it, or does it with a different gesture or name. |')
lines.push('| **PLANNED** | Drawn for the layout study. Nothing behind it in Dex. |')
lines.push('')
lines.push(
  `**${numbered.length} controls** — ${count('live')} live, ${count('partial')} partial, ${count('planned')} planned.`
)
lines.push('')
lines.push('## Using the mockup')
lines.push('')
lines.push('Open `mockup/xdj-mixer-alt.html` in a browser. Two switches in the top bar drive this map:')
lines.push('')
lines.push('- **Function map** — outlines every control and numbers it, matching the `#` column below.')
lines.push('- **Controls** — opens the side panel. Click any control in the mockup, or any row in the panel, to read')
lines.push('  what it does, its shortcut, and the file it lives in.')
lines.push('')
lines.push('Numbers are stable: they come from the order of `controls.json`, not from the plan being viewed.')
lines.push('Mirrored controls (deck A and deck B) share one number and highlight together.')
lines.push('')

for (const group of byGroup) {
  if (group.controls.length === 0) continue
  lines.push(`## ${esc(group.title)}`)
  lines.push('')
  if (group.blurb) {
    lines.push(`${group.blurb}`)
    lines.push('')
  }
  lines.push('| # | Control | Status | What it does in Dex | Key | Source |')
  lines.push('| --- | --- | --- | --- | --- | --- |')
  for (const control of group.controls) {
    const source = control.source ? `\`${control.source}\`` : '—'
    lines.push(
      `| ${control.n} | **${esc(control.label)}** | ${control.status.toUpperCase()} | ${esc(control.does)} | ` +
        `${control.shortcut ? `\`${esc(control.shortcut)}\`` : '—'} | ${source} |`
    )
  }
  lines.push('')
}

const withShortcut = numbered.filter((control) => control.shortcut)
if (withShortcut.length > 0) {
  lines.push('## Shortcuts on the drawn controls')
  lines.push('')
  lines.push('| Keys | Control |')
  lines.push('| --- | --- |')
  for (const control of withShortcut) {
    lines.push(`| \`${esc(control.shortcut)}\` | ${esc(control.label)} (#${control.n}) |`)
  }
  lines.push('')
  lines.push(
    'The in-app `?` sheet is authoritative for keys that have no drawn control — arrow-key grid nudging,'
  )
  lines.push('for instance.'
  )
  lines.push('')
}

await writeFile(join(ROOT, 'docs', 'CONTROL-MAP.md'), lines.join('\n'), 'utf8')

/* ---------- cross-check the mockup against the map ---------- */
const html = await readFile(join(HERE, 'xdj-mixer-alt.html'), 'utf8')
const referenced = new Set()
// Skip the template placeholders (`data-ctl="${id}"`) — only literal ids count.
const isId = (value) => /^[a-z][a-z0-9.]*$/i.test(value)
for (const match of html.matchAll(/data-ctl="([^"]+)"/g)) if (isId(match[1])) referenced.add(match[1])
for (const match of html.matchAll(/fader[VH]\('([^']+)'/g)) if (isId(match[1])) referenced.add(match[1])

const orphans = [...referenced].filter((id) => !seen.has(id))
// Some ids are handed to a render helper rather than written as data-ctl, so
// accept any quoted occurrence in the page for the second direction.
const unmounted = [...seen].filter(
  (id) => !html.includes(`'${id}'`) && !html.includes(`"${id}"`) && !html.includes(`data-ctl="${id}"`)
)

console.log(`controls.json      ${numbered.length} controls (${count('live')} live, ${count('partial')} partial, ${count('planned')} planned)`)
console.log(`controls.data.js   written`)
console.log(`CONTROL-MAP.md     written`)
console.log(`mockup anchors     ${referenced.size} literal data-ctl values`)
if (unmounted.length > 0) console.log(`  not in the mockup: ${unmounted.join(', ')}`)
if (orphans.length > 0) console.log(`  in the mockup but not the map: ${orphans.join(', ')}`)
if (unmounted.length === 0 && orphans.length === 0) {
  console.log('  every control is anchored, every anchor is described')
} else {
  process.exitCode = 1
  console.error('\nAdd the missing ids to controls.json (or fix the data-ctl spelling) and run again.')
}
